// Feature::Collab（key="multi_agent"，default=true）已启用
// 向模型提供的工具集（tool_config.rs:146）：
//   spawn_agent     — 创建子 Agent（V1/V2）
//   send_input      — 发送消息给已存在 Agent（V1）
//   send_message    — 发送消息不触发 turn（V2）
//   followup_task   — 发送消息并触发新 turn（V2）
//   wait_agent      — 等待一个或多个 Agent 完成
//   close_agent     — 关闭 Agent 及其子树
//   list_agents     — 列出当前所有 live Agent

// SubAgentSource 枚举（protocol.rs:2623）全部变体：
//   ThreadSpawn { parent_thread_id, depth, agent_path, agent_nickname, agent_role }
//   MemoryConsolidation
//   Review
//   Compact
//   Other(String)   — e.g. "agent_job:<id>"

{
  "tool": "spawn_agent",
  "arguments": {
    "task_name": "auth-service-docs",
    "message": "分析 services/auth/ 目录，生成架构文档，保存到 docs/auth.md",
    "agent_type": "architect",
    "fork_turns": "none",
    "model": null,
    "reasoning_effort": null
  }
}

// control.rs:151 spawn_agent_internal() 六步执行：

// 1. reserve_spawn_slot()
//    AgentRegistry 检查并发限制（agent_max_threads）
//    → SpawnReservation { slot: 3 }

// 2. inherited_shell_snapshot_for_source()
//    ThreadSpawn 类型 → 从父线程继承 shell 快照

// 3. apply_spawn_agent_runtime_overrides(config)
//    从父 turn 复制：sandbox_policy, approval_policy,
//    shell_environment_policy, cwd, model, reasoning_effort
//    history: 空（fork_turns=none）

// 4. prepare_thread_spawn()
//    agent_path = /root/main/auth-service-docs
//    agent_nickname = "auth-service-docs"

// 5. spawn_new_thread_with_source(SubAgentSource::ThreadSpawn{..})
//    → new_thread_id = ThreadId("019e3f..")
//    → thread/started 通知发送给所有客户端

// 6. send_input(Op::UserTurn { .. })
//    子 Agent 开始运行
// → maybe_start_completion_watcher() 启动 tokio::spawn 监听完成
